import{_ as a,o as e,c as i,a5 as c}from"./chunks/framework.DJo0M80U.js";const h=JSON.parse('{"title":"精度问题","description":"是的，JavaScript 中的乘法运算可能会遇到精度问题，特别是在处理浮点数时。 为什么会发生精度问题 JavaScript 使用 IEEE 754 标准的 64 位双精度浮点数来表示所有数字（包括整数和小数），这会导致： 2. 某些小数无法精确表示：例如 0.1 + 0.2。","frontmatter":{"title":"精度问题","date":"2026-08-11T00:00:00.000Z","categories":["JavaScript 系统教程"],"tags":["JavaScript","前端","教程","OneNote","语法、变量与数据"],"description":"是的，JavaScript 中的乘法运算可能会遇到精度问题，特别是在处理浮点数时。 为什么会发生精度问题 JavaScript 使用 IEEE 754 标准的 64 位双精度浮点数来表示所有数字（包括整数和小数），这会导致： 2. 某些小数无法精确表示：例如 0.1 + 0.2。","sidebarWeight":56,"lastUpdated":false,"feed":false,"source":"onenote","sourceNote":"OneNote/b-原生js/基本数据类型-数字/精度问题.md"},"headers":[],"relativePath":"posts/JavaScript系统教程/02-语法、变量与数据/精度问题.md","filePath":"posts/JavaScript系统教程/02-语法、变量与数据/精度问题.md"}'),o={name:"posts/JavaScript系统教程/02-语法、变量与数据/精度问题.md"};function l(r,t,s,n,p,d){return e(),i("div",null,[...t[0]||(t[0]=[c('<div><h1 id="精度问题" tabindex="-1">精度问题 <a class="header-anchor" href="#精度问题" aria-label="Permalink to &quot;精度问题&quot;">​</a></h1><blockquote><p>本节目标：理解“精度问题”的核心思路，并能把它用于实际开发或面试表达。 是的，JavaScript 中的乘法运算可能会遇到精度问题，特别是在处理浮点数时。 为什么会发生精度问题 JavaScript 使用 IEEE 754 标准的 64 位双精度浮点数来表示所有数字（包括整数和小数），这会导致：</p></blockquote><ol start="2"><li>某些小数无法精确表示：例如 0.1 + 0.2 ≠ 0.3</li><li>大整数可能丢失精度：当数字超过 2^53 (约 9千万亿) 时</li></ol><p>乘法精度问题示例 javascript console.log(0.1 * 0.2); // 0.020000000000000004 而不是 0.02console.log(1.005 * 100); // 100.49999999999999 而不是 100.5console.log(12345678901234567 * 10); // 123456789012345680 而不是 123456789012345670 解决方案</p><ol start="5"><li>使用 toFixed() 方法（注意这会返回字符串）：javascript(0.1 * 0.2).toFixed(2); // &quot;0.02&quot;</li><li>转换为整数计算后再转换回去：javascriptfunction multiply(a, b) { const factor = Math.pow(10, Math.max(getDecimalLength(a), getDecimalLength(b))); return (a * factor) * (b * factor) / (factor * factor);}function getDecimalLength(num) { const decimal = num.toString().split(&#39;.&#39;)[1]; return decimal ? decimal.length : 0;}</li><li>使用第三方库：</li><li>decimal.js</li><li>big.js</li><li>math.js</li><li>对于大整数，使用 BigInt（ES2020 引入）：javascriptconst bigNum = BigInt(12345678901234567) * 10n;</li></ol><p>最佳实践</p><ol start="13"><li>对于金融计算等需要高精度的场景，始终使用专门的库</li><li>了解你的数字范围，必要时使用 BigInt</li><li>显示结果时使用 toFixed() 或类似方法进行格式化</li></ol><p>JavaScript 的这种行为并非缺陷，而是 IEEE 754 浮点数标准的特性，大多数编程语言都有类似问题。 &gt; 来自 &lt;<a href="https://chat.deepseek.com/a/chat/s/0a20c85b-861b-4985-9c0e-fb77f8517885" target="_blank" rel="noreferrer">https://chat.deepseek.com/a/chat/s/0a20c85b-861b-4985-9c0e-fb77f8517885</a>&gt; &gt; 来自 &lt;<a href="https://chat.deepseek.com/a/chat/s/0a20c85b-861b-4985-9c0e-fb77f8517885" target="_blank" rel="noreferrer">https://chat.deepseek.com/a/chat/s/0a20c85b-861b-4985-9c0e-fb77f8517885</a>&gt;</p></div>',1)])])}const m=a(o,[["render",l]]);export{h as __pageData,m as default};
